    logic        ent_is_store  [0:1];
    logic [1:0]  ent_mem_size  [0:1];
    logic [1:0]  ent_epoch     [0:1];
    logic        ent_issued    [0:1];
    logic        ent_wait_resp [0:1];
    logic        ent_committed [0:1];

    // External request holding.  Once req_valid/address are presented they
    // must remain stable until req_ready, even if the originating entry is
    // squashed by a redirect.
    logic        req_active;
    logic        req_we_q;
    logic [31:0] req_addr_q;
    logic [31:0] req_wdata_q;
    logic [3:0]  req_be_q;
    logic [3:0]  req_rob_q;
    logic [1:0]  req_epoch_q;

    logic        head_valid;
    logic        tail_valid;
    logic        head_rs1_wake;
    logic        head_rs2_wake;
    logic        tail_rs1_wake;
    logic        tail_rs2_wake;
