    logic        req_owner_match;
    logic        head_resp_fire;
    logic        head_resp_stale;
    logic        head_load_done;
    logic        head_store_done;
    logic [31:0] head_addr;
    logic [3:0]  head_be;
    logic [31:0] head_wdata;
    logic [31:0] load_word;
    logic [31:0] load_data;
    logic [2:0]  head_funct3;
    logic        disp_fire;
    logic        disp_to_head;
    logic        disp_to_tail;
    logic        disp_rs1_eff;
    logic        disp_rs2_eff;
    logic        squash_head;
    logic        squash_tail;
    logic        store_commit_match_head;
    logic        store_commit_match_tail;
    logic        head_remove;
    logic        tail_remove;

    // Single prioritized next-state values for the per-entry operand-ready
    // bits.  Dispatch, same-cycle producer wakeup and head/tail compaction
    // are all resolved here so no later assignment can ever clobber a
    // wakeup that arrived in the same cycle.
    logic        head_rs1_next;
    logic        head_rs2_next;
    logic        tail_rs1_next;
    logic        tail_rs2_next;

    assign head_valid = ent_valid[0];
    assign tail_valid = ent_valid[1];

    assign lsu_prf_rs1_addr = ent_valid[0] ? ent_prs1[0] :
                              (ent_valid[1] ? ent_prs1[1] : 6'd0);
    assign lsu_prf_rs2_addr = ent_valid[0] ? ent_prs2[0] :
                              (ent_valid[1] ? ent_prs2[1] : 6'd0);

