// -----------------------------------------------------------------------------
// Local direct-mapped instruction cache, same port contract as plan `icache`.
// -----------------------------------------------------------------------------
module rv32i5_icache (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        flush,
    input  logic [1:0]  flush_epoch,
    input  logic        halted,
    input  logic        cpu_req_valid,
    input  logic [31:0] cpu_req_addr,
    input  logic [1:0]  cpu_req_epoch,
    output logic        cpu_req_ready,
    output logic        cpu_resp_valid,
    output logic [31:0] cpu_resp_data,
    output logic [1:0]  cpu_resp_epoch,
    output logic        mem_req_valid,
    input  logic        mem_req_ready,
    output logic [31:0] mem_req_addr,
    input  logic        mem_resp_valid,
    input  logic [31:0] mem_resp_data,
    output logic        idle
);

    localparam logic [1:0] ST_IDLE   = 2'd0;
    localparam logic [1:0] ST_REFILL = 2'd1;
    localparam logic [1:0] ST_RESP   = 2'd2;

    logic [1:0]   state;

    logic [127:0] line_data  [0:15];
    logic [23:0]  line_tag   [0:15];
    logic [15:0]  line_valid;

    logic [31:0] req_addr;
    logic [1:0]  req_epoch;

    logic [31:0]  refill_base;
    logic [1:0]   refill_word;
    logic [127:0] refill_data;
    logic [127:0] refill_next;
    logic [23:0]  refill_tag;
    logic [3:0]   refill_idx;

    logic [31:0] resp_data_r;
    logic [1:0]  resp_epoch_r;

    logic [3:0]  cpu_idx;
    logic [23:0] cpu_tag;
    logic [1:0]  cpu_wsel;
    logic        cpu_hit;
    logic [31:0] cpu_word;
    logic [127:0] cpu_line;

    logic [1:0]  ref_wsel;
    logic [31:0] ref_word;

    assign cpu_idx  = cpu_req_addr[7:4];
    assign cpu_tag  = cpu_req_addr[31:8];
    assign cpu_wsel = cpu_req_addr[3:2];

    always_comb begin
        cpu_line = line_data[cpu_idx];
        cpu_hit  = line_valid[cpu_idx] && (line_tag[cpu_idx] == cpu_tag);
        case (cpu_wsel)
            2'd0:    cpu_word = cpu_line[31:0];
            2'd1:    cpu_word = cpu_line[63:32];
            2'd2:    cpu_word = cpu_line[95:64];
            default: cpu_word = cpu_line[127:96];
        endcase
    end

    assign ref_wsel = req_addr[3:2];
    always_comb begin
        case (ref_wsel)
            2'd0:    ref_word = refill_next[31:0];
            2'd1:    ref_word = refill_next[63:32];
            2'd2:    ref_word = refill_next[95:64];
            default: ref_word = refill_next[127:96];
        endcase
    end

    always_comb begin
        refill_next = refill_data;
        case (refill_word)
            2'd0:    refill_next[31:0]    = mem_resp_data;
            2'd1:    refill_next[63:32]   = mem_resp_data;
            2'd2:    refill_next[95:64]   = mem_resp_data;
            default: refill_next[127:96]  = mem_resp_data;
        endcase
    end

    // rst_n must gate the ready output: accepting a request while reset is
    // still asserted (combinational ready high) would latch the not-yet-reset
    // PC/X address and start a bogus refill that survives reset, corrupting
    // the very first fetched line and hanging the core.
    assign cpu_req_ready  = rst_n && (state == ST_IDLE) && !halted;

    assign cpu_resp_valid = rst_n && (state == ST_RESP);
    assign cpu_resp_data  = resp_data_r;
    assign cpu_resp_epoch = resp_epoch_r;

    assign mem_req_valid = rst_n && (state == ST_REFILL);
    assign mem_req_addr  = refill_base + {refill_word, 2'b00};

    assign idle = rst_n && (state == ST_IDLE) && !cpu_req_valid;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            state        <= ST_IDLE;
            line_valid   <= 16'b0;
            req_addr     <= 32'b0;
            req_epoch    <= 2'b0;
            refill_base  <= 32'b0;
            refill_word  <= 2'b0;
            refill_data  <= 128'b0;
            refill_tag   <= 24'b0;
            refill_idx   <= 4'b0;
            resp_data_r  <= 32'b0;
            resp_epoch_r <= 2'b0;
        end else begin
            case (state)
                ST_IDLE: begin
                    if (cpu_req_valid && !halted) begin
                        req_addr  <= cpu_req_addr;
                        req_epoch <= cpu_req_epoch;
                        if (cpu_hit) begin
                            resp_data_r  <= cpu_word;
                            resp_epoch_r <= cpu_req_epoch;
                            state        <= ST_RESP;
                        end else begin
                            refill_base <= {cpu_req_addr[31:4], 4'b0000};
                            refill_tag  <= cpu_req_addr[31:8];
                            refill_idx  <= cpu_req_addr[7:4];
                            refill_word <= 2'b00;
                            refill_data <= 128'b0;
                            state       <= ST_REFILL;
                        end
                    end
                end
                ST_REFILL: begin
                    if (mem_req_ready) begin
                        refill_data <= refill_next;
                        if (refill_word == 2'b11) begin
                            line_data[refill_idx]  <= refill_next;
                            line_tag[refill_idx]   <= refill_tag;
                            line_valid[refill_idx] <= 1'b1;
                            resp_data_r  <= ref_word;
                            resp_epoch_r <= req_epoch;
                            state        <= ST_RESP;
                        end else begin
                            refill_word <= refill_word + 2'b01;
                        end
                    end
                end
                ST_RESP: begin
                    state <= ST_IDLE;
                end
                default: state <= ST_IDLE;
            endcase
        end
    end

endmodule
"
    }
  ],
  "notes": "Root cause 1 (data): load_store_unit decoded sub-word loads with a fixed sign-extension and used only mem_size[0] so the word branch was unreachable. The load result now decodes the real instruction funct3: LB/LH sign-extend, LBU/LHU zero-extend, LW full word. Store byte-enable/data generation now also uses funct3 (SB byte lanes and SH half lanes unchanged; SW now drives all four byte lanes instead of being mis-decoded as a byte/half store). Root cause 2 (OoO evidence): issue_queue.dbg_ooo_bypass was ANDed with ent_older_load_pending, which can never be true because loads are dispatched to the LSU, not the IQ, so bypass was stuck at 0; it is now a real single-cycle out-of-order issue event (issue while the ROB head is still older). rv32i5 now derives dbg_ooo_issue/dbg_ooo_bypass combinationally from the real IQ issue event (same-cycle pulse, not a counter/PC pattern) and qualifies bypass with the real LSU outstanding state (req_valid | dcache_wait | resp_valid), so a younger ALU issued while an older load waits for external memory is visible. Timing corners checked: reset (all dbg/req signals 0, dmem_valid gated by rst_n), retire pulse uniqueness (commit_unit unchanged: one pulse per ROB commit, ECALL wait path suppresses repeats), halt/exit_code commit timing unchanged, stall/flush valid handling unchanged (IQ issue/dispatch still gated by !flush, LSU still holds req_valid/addr until ready), and LSU response capture remains unconditional on resp_valid with epoch checks."
}

