    logic        commit_valid;
    logic [31:0] commit_pc;
    logic [31:0] commit_insn;
    logic [31:0] commit_value;
    logic [4:0]  commit_arch_rd;
    logic        commit_reg_write;
    logic        commit_is_ecall;
    logic        commit_old_prd_valid;
    logic [5:0]  commit_old_prd;

    // ---------------- debug masks ----------------
    logic        evt_en;
    logic        bp_resolve_raw;
    logic        bp_mispredict_raw;
    logic        ooo_issue_raw;
    logic        ooo_bypass_raw;
    logic        iq_dbg_ooo_issue;
    logic        iq_dbg_ooo_bypass;
    logic        lsu_mem_pending;

    // bus_idle is the commit unit's condition for retiring the ECALL.  Only
    // the DATA side can affect an ECALL's architectural commit: the ECALL is
    // not a memory operation, so an I-side transaction that was issued for a
    // (never committed) younger instruction must not hold bus_idle low -- that
    // is exactly the case where the ECALL waits in WB forever and the core
    // never halts (simulation timeout).  While an ECALL is pending the I-side
