    assign lsu_issue_accept  = lsu_disp_valid && lsu_disp_ready;
    assign bp_resolve_raw    = resolve_valid;
    assign bp_mispredict_raw = resolve_mispredict;
    assign ooo_issue_raw     = iq_dbg_ooo_issue || lsu_issue_accept;
